SELECT t.project_name, t.buy_user_name, t.buy_budget_money, t.open_bid_time, t.unicom_type, t.competition_condition, t.bid_result, t.bid_body, t.project_type, t.match_bid_money, t.expected_main_operating_amount, t.ict_profit, t.is_framework_contract, t.contract_time, t.opp_code, t.opp_name, t.opp_dept_name, t.opp_manager, t.main_support_dept_name, t.support_role, t.support_manager, t.work_days, t.contribution, t.personal_contribution_amount FROM ( SELECT a.project_name, a.buy_user AS buy_user_name, CASE WHEN a.buy_budget_money IS NOT NULL THEN ROUND(a.buy_budget_money, 2) ELSE NULL END AS buy_budget_money, DATE_FORMAT(a.open_bid_time, '%Y-%m-%d') AS open_bid_time, c.unicom_type, a.competition_condition, a.result AS bid_result, a.bid_body, a.project_type, CASE WHEN a.match_bid_money IS NOT NULL THEN ROUND(a.match_bid_money, 2) ELSE NULL END AS match_bid_money, CASE WHEN a.expected_main_operating_amount IS NOT NULL THEN ROUND(a.expected_main_operating_amount, 2) ELSE NULL END AS expected_main_operating_amount, CASE WHEN a.ict_profit IS NOT NULL THEN ROUND(a.ict_profit, 2) ELSE NULL END AS ict_profit, a.is_framework_contract, a.contract_time, c.opp_code, c.opp_name, f.dept_name AS opp_dept_name, d.nick_name AS opp_manager, g.dept_name AS main_support_dept_name, '支撑经理' AS support_role, i.nick_name AS support_manager, th.hours AS work_days, ci.contribution, ci.grgxed AS personal_contribution_amount FROM topp_bid_new a INNER JOIN topp_bid_new_score b ON a.id = b.topp_bid_new_id INNER JOIN topp_opportunity c ON c.id_ = b.opportunity_code INNER JOIN zqzt_sys_user d ON c.cust_manager_id = d.user_id INNER JOIN zqzt_sys_user e ON c.designer = e.user_id INNER JOIN zqzt_sys_dept f ON d.dept_id = f.dept_id INNER JOIN zqzt_sys_dept g ON e.dept_id = g.dept_id INNER JOIN topp_member h ON h.project_id = c.id_ AND h.member_role = 'member_role_zcjl' AND h.member_id != c.designer INNER JOIN zqzt_sys_user i ON h.member_id = i.user_id LEFT JOIN ( SELECT info_id, actor_, SUM(support_hours) AS hours FROM tcomm_task WHERE actor_ IS NOT NULL GROUP BY info_id, actor_ ) th ON th.info_id = c.id_ AND th.actor_ = h.member_id LEFT JOIN ( SELECT b.topp_bid_new_id AS bid_id, b.name AS member_name, b.contribution, ROUND(IFNULL(a.match_bid_money, 0) * b.contribution / 100, 2) AS grgxed FROM topp_bid_new a INNER JOIN topp_bid_new_score b ON a.id = b.topp_bid_new_id GROUP BY a.id, b.name, b.contribution ) ci ON ci.bid_id = a.id AND ci.member_name = h.name_ WHERE a.is_sign = '0' and e.dept_id in( select dept_id from zqzt_sys_dept where dept_id = #{deptId} union select t.dept_id from (select * from zqzt_sys_dept where parent_id is not null) t, (select @parent_id := #{deptId}) pd where FIND_IN_SET(parent_id,@parent_id) > 0 and @parent_id := CONCAT(@parent_id,',',dept_id) )
and a.buy_budget_money >= #{minCgAmount}
and a.buy_budget_money < #{maxCgAmount}
and a.match_bid_money >= #{minYjAmount}
and a.match_bid_money < #{maxYjAmount}
and c.expect_contract_money >= #{minSjAmount}
and c.expect_contract_money < #{maxSjAmount}
and a.bid_body in
#{item}
and a.competition_condition in
#{item}
and a.project_type in
#{item}
and a.result = #{bidResult}
and a.ict_profit>= #{minMll}
and a.ict_profit <= #{maxMll}
and a.open_bid_time >= #{startTime}
and a.open_bid_time <= #{endTime}
and c.unicom_type in
#{item}
